1	/**
2	 * Cloud inference providers: one declaration per provider feeds configuration, credential scoping, disclosure policy
3	 * and request construction. The local appliance is not a provider here: a configuration without a provider id keeps
4	 * the original endpoint path (LOCAL_LLM_*, stored gateway token, X-Task-Class, endpoint failover) unchanged.
5	 *
6	 * Separate concepts:
7	 * - Provider definition (PROVIDERS): identity, wire protocol, default base URL, credential variable, auth style.
8	 * - Connection (ResolvedConnection): the base URL actually used, its credential scope and disclosure class.
9	 * - Model: the provider's model id, passed verbatim (ids may contain "/" and ":").
10	 * - Role binding: main, planner and coder each name their own provider; subagents and auxiliary calls inherit main.
11	 */
12	import { classifyDestination } from "./core/egress.js";
13	
14	export type WireProtocol = "openai-chat" | "openai-responses" | "anthropic-messages";
15	export type AuthStyle = "bearer" | "x-api-key" | "none" | "oauth";
16	
17	/** How an operator can connect a provider from the TUI or `nexus connect`. */
18	export interface ConnectMethod {
19	  id: string;
20	  label: string;
21	  kind: "key" | "browser" | "device";
22	  /** Uses another vendor's client identity; the providers' terms may not permit it. */
23	  unofficial?: boolean;
24	}
