33	  credentialEnv?: string;
34	  methods: ConnectMethod[];
35	  /** The backend accepts streamed requests only; non-streaming calls are streamed internally. */
36	  streamOnly?: boolean;
37	  /** Request parameters this backend rejects for every model; never sent. */
38	  omitParams?: string[];
39	  auth: AuthStyle;
40	  /** Headers this provider requires on every request. */
41	  staticHeaders?: Record<string, string>;
42	  /** Ask the provider to report usage (and, where offered, cost) on streamed responses. */
43	  usage: "openrouter" | "stream-options" | "native";
44	}
