63	    label: "OpenAI",
64	    protocol: "openai-responses",
65	    baseUrl: "https://api.openai.com/v1",
66	    credentialEnv: "OPENAI_API_KEY",
67	    auth: "bearer",
68	    usage: "native",
69	    methods: [{ id: "api-key", label: "API key", kind: "key" }],
70	  },
71	  anthropic: {
72	    id: "anthropic",
73	    label: "Anthropic",
74	    protocol: "anthropic-messages",
75	    baseUrl: "https://api.anthropic.com/v1",
76	    credentialEnv: "ANTHROPIC_API_KEY",
77	    auth: "x-api-key",
78	    staticHeaders: { "anthropic-version": "2023-06-01" },
79	    usage: "native",
80	    methods: [{ id: "api-key", label: "API key", kind: "key" }],
81	  },
82	  /** ChatGPT Plus/Pro plan through the Codex backend (unofficial: Codex CLI sign-in). */
83	  chatgpt: {
84	    id: "chatgpt",
85	    label: "ChatGPT plan",
