128	  if (!url?.trim()) return undefined;
129	  try {
130	    return new URL(url.trim()).origin;
131	  } catch {
132	    return undefined;
133	  }
134	}
135	
136	export interface ResolvedConnection {
137	  /** Undefined for the legacy appliance/endpoint path. */
138	  providerId?: string;
139	  label: string;
140	  protocol: WireProtocol;
141	  auth: AuthStyle;
142	  staticHeaders: Record<string, string>;
143	  usage: ProviderDefinition["usage"] | "none";
144	  /** Whether requests carry the appliance's X-Task-Class routing hint. */
145	  sendTaskClass: boolean;
146	  streamOnly: boolean;
147	  omitParams: string[];
148	}
149	
150	/** Copilot serves some models through the Responses API only. */
151	export function protocolFor(providerId: string | undefined, model: string): WireProtocol | undefined {
152	  if (providerId === "copilot" && /^gpt-5/i.test(model)) return "openai-responses";
153	  return undefined;
154	}
155	
156	export function connectionFor(providerId: string | undefined, model = ""): ResolvedConnection {
157	  const def = providerDefinition(providerId);
158	  if (!def) {
159	    // Usage is requested (OpenAI-compatible servers such as llama.cpp, vLLM and the appliance gateway report it, with
160	    // cached-token counts); a server that rejects stream_options has it dropped and the request retried.
161	    return { label: "endpoint", protocol: "openai-chat", auth: "bearer", staticHeaders: {}, usage: "stream-options", sendTaskClass: true, streamOnly: false, omitParams: [] };
162	  }
163	  return {
164	    providerId: def.id,
165	    label: def.label,
166	    protocol: protocolFor(def.id, model) ?? def.protocol,
167	    auth: def.auth,
168	    staticHeaders: { ...(def.staticHeaders ?? {}) },
169	    usage: def.usage,
170	    sendTaskClass: false,
171	    streamOnly: Boolean(def.streamOnly),
172	    omitParams: [...(def.omitParams ?? [])],
173	  };
174	}
175	
176	/**
177	 * Disclosure class of a destination: "cloud" when content sent there leaves the operator's machines and network.
178	 * URL locality is not sufficient: an origin the operator lists in NEXUS_CLOUD_ROUTED_ORIGINS (a local gateway that
179	 * forwards to a cloud service) is cloud, and every named provider except `compatible` is cloud by definition.
180	 */
181	export function disclosureClass(url: string, providerId: string | undefined, cloudRoutedOrigins: readonly string[] = []): "local" | "cloud" {
182	  if (providerId && providerId !== "compatible") return "cloud";
183	  const origin = originOf(url);
184	  if (origin && cloudRoutedOrigins.includes(origin)) return "cloud";
185	  const boundary = classifyDestination(url);
186	  return boundary === "EXTERNAL_PUBLIC" || boundary === "EXTERNAL_BOUNDED" ? "cloud" : "local";
187	}
188	
189	export function parseOriginList(raw: string | undefined): string[] {
190	  return (raw ?? "").split(",").map((o) => originOf(o)).filter((o): o is string => Boolean(o));
191	}
192	
193	/** The environment variable a provider connection reads its key from (for operator-facing messages). */
194	export function operatorSettingKeyForAuth(id: string): string {
195	  const def = providerDefinition(id);
196	  return def?.credentialEnv ?? (def ? `sign in with /model → ctrl+p → ${def.label}` : "the provider's API key variable");
197	}
