1	/**
2	 * What the model picker shows: the appliance and every cloud provider, whether and how each is connected, the models
3	 * each lists, and the operator's recent selections. Listing never blocks on a slow or offline provider: each list
4	 * is fetched with a timeout and falls back to the last good list cached in ~/.cache/nexus/models.
5	 */
6	import * as fs from "node:fs";
7	import * as path from "node:path";
8	import { createHash } from "node:crypto";
9	import { credentialStorageHome, LocalLlmClient, operatorSetting } from "./client.js";
10	import { applianceEndpointSelection, buildConfig, providerBaseUrl, providerKey } from "./config.js";
11	import { resolveCredential } from "./credentials.js";
12	import { comparableEndpoint, scrubUrls } from "./core/endpoint_identity.js";
13	import { originOf, PROVIDERS, providerDefinition, type ConnectMethod } from "./providers.js";
14	import { redactSecrets } from "./ui.js";
15	import type { HarnessConfig } from "./types.js";
16	
17	/** The appliance's id in the picker (it is not a cloud provider). */
18	export const APPLIANCE = "appliance";
19	/**
20	 * The endpoint this session is running on when it is neither the appliance nor a cloud provider (a `-e` flag or the
21	 * environment): the picker lists its own models, so the working endpoint and the current model are visible.
22	 */
23	export const SESSION_ENDPOINT = "session";
24	
25	/** A model list is untrusted server output: at most this many entries, each this long and printable. */
26	const MAX_LISTED_MODELS = 1000;
27	const MAX_MODEL_ID = 200;
28	
29	export interface CatalogProvider {
30	  id: string;
31	  label: string;
32	  /** "local" for the appliance, "cloud" otherwise. */
33	  disclosure: "local" | "cloud";
34	  connected: boolean;
35	  /** Where the connection's credential comes from ("$OPENROUTER_API_KEY", "Nexus", "Codex CLI", ...). */
36	  source?: string;
37	  /** True when the credential is read from another client (Codex CLI, opencode, crush, Copilot plugin). */
38	  external?: boolean;
39	  methods: ConnectMethod[];
40	  status: "ok" | "cached" | "error" | "disconnected";
41	  error?: string;
42	}
43	
44	export interface CatalogModel {
45	  provider: string;
46	  id: string;
47	}
48	
49	export interface ModelRef {
50	  provider: string;
51	  model: string;
52	}
53	
54	export interface Catalog {
55	  providers: CatalogProvider[];
56	  models: CatalogModel[];
57	  current: ModelRef;
58	  recent: ModelRef[];
59	}
60	
61	const MAX_RECENT = 8;
62	const stateFile = () => path.join(credentialStorageHome(), ".local/state/nexus/recent-models.json");
63	const cacheFile = (id: string) => path.join(credentialStorageHome(), ".cache/nexus/models", `${id.replace(/[^a-z0-9_-]/gi, "_")}.json`);
64	
65	function cacheId(providerId: string, endpoint: string): string {
66	  let identity = endpoint.trim();
67	  try {
68	    const normalized = new URL(identity);
69	    normalized.hash = "";
70	    identity = normalized.toString().replace(/\/+$/, "");
71	  } catch {}
72	  return `${providerId}-${createHash("sha256").update(identity).digest("hex").slice(0, 20)}`;
73	}
74	
75	export function readRecent(): ModelRef[] {
76	  try {
77	    const raw = JSON.parse(fs.readFileSync(stateFile(), "utf-8"));
78	    return Array.isArray(raw) ? raw.filter((r) => typeof r?.provider === "string" && typeof r?.model === "string").slice(0, MAX_RECENT) : [];
79	  } catch {
80	    return [];
81	  }
82	}
83	
84	export function recordRecent(ref: ModelRef): void {
85	  const list = [ref, ...readRecent().filter((r) => r.provider !== ref.provider || r.model !== ref.model)].slice(0, MAX_RECENT);
86	  try {
87	    fs.mkdirSync(path.dirname(stateFile()), { recursive: true });
88	    fs.writeFileSync(stateFile(), JSON.stringify(list, null, 2) + "\n");
89	  } catch {}
90	}
91	
92	/** Chat-capable entries of a provider's list (OpenAI and Copilot lists also carry embedding/audio/image models). */
93	export function chatModel(providerId: string, id: string): boolean {
94	  if (/(embedding|rerank|tts|whisper|dall-e|gpt-image|audio|realtime|transcribe|moderation|davinci|babbage)/i.test(id)) return false;
95	  if (providerId === "openai") return /^(gpt-|o\d|chatgpt-|codex)/i.test(id);
96	  return true;
97	}
98	
99	function cached(id: string): string[] | undefined {
100	  try {
101	    const raw = JSON.parse(fs.readFileSync(cacheFile(id), "utf-8"));
102	    return Array.isArray(raw?.models) ? raw.models : undefined;
103	  } catch {
104	    return undefined;
105	  }
106	}
107	
108	function cache(id: string, models: string[]): void {
109	  try {
110	    fs.mkdirSync(path.dirname(cacheFile(id)), { recursive: true });
111	    fs.writeFileSync(cacheFile(id), JSON.stringify({ fetchedAt: new Date().toISOString(), models }) + "\n");
112	  } catch {}
113	}
114	
115	async function withTimeout<T>(p: Promise<T>, ms: number, signal?: AbortSignal): Promise<T> {
116	  let t: NodeJS.Timeout | undefined;
117	  let onAbort: (() => void) | undefined;
118	  try {
119	    return await Promise.race([
120	      p,
121	      new Promise<T>((_, rej) => { t = setTimeout(() => rej(new Error(`no answer within ${ms / 1000}s`)), ms); }),
122	      new Promise<T>((_, rej) => {
123	        if (!signal) return;
124	        onAbort = () => rej(new Error("cancelled"));
125	        if (signal.aborted) onAbort();
126	        else signal.addEventListener("abort", onAbort, { once: true });
127	      }),
128	    ]);
129	  } finally {
130	    clearTimeout(t);
131	    if (onAbort) signal?.removeEventListener("abort", onAbort);
132	  }
133	}
134	
135	/**
136	 * Bounded model ids with no control, format (bidi, zero-width) or line-separator character. An id that has one is
137	 * dropped, not cleaned: a cleaned id would differ from what the server lists and could be selected as another model.
138	 */
139	function listedIds(ids: unknown[]): string[] {
140	  const out: string[] = [];
141	  for (const raw of ids) {
142	    if (typeof raw !== "string" || !raw.trim() || raw !== raw.trim() || raw.length > MAX_MODEL_ID || /[\p{Cc}\p{Cf}\u2028\u2029]/u.test(raw)) continue;
143	    out.push(raw);
144	    if (out.length >= MAX_LISTED_MODELS) break;
145	  }
146	  return out;
147	}
148	
149	function sameEndpoint(a: string, b: string): boolean {
150	  return comparableEndpoint(a) === comparableEndpoint(b);
151	}
152	
153	/** The appliance connection, whatever provider is currently selected. */
154	export function applianceConfig(base: HarnessConfig): HarnessConfig {
155	  try {
156	    const config = buildConfig({ appliance: true });
157	    const selection = applianceEndpointSelection();
158	    const origin = selection ? originOf(selection.endpoint) : undefined;
159	    return {
160	      ...config,
161	      workspace: base.workspace,
162	      ...(origin ? { authorizedDisclosureOrigins: [...new Set([...(config.authorizedDisclosureOrigins ?? []), origin])] } : {}),
163	    };
164	  } catch {
165	    return { ...base, provider: undefined };
166	  }
167	}
168	
169	/** A connection config for `providerId` with its own key (sign-in providers resolve theirs per request). */
170	export function providerConfig(base: HarnessConfig, providerId: string, model = ""): HarnessConfig {
171	  const endpoint = providerBaseUrl(providerId);
172	  const origin = originOf(endpoint)!;
173	  return {
174	    ...base,
175	    provider: providerId,
176	    endpoint,
177	    model,
178	    apiKey: providerKey(providerId),
179	    credentialOrigin: origin,
180	    fallbackEndpoints: undefined,
181	    pinEndpoint: true,
182	    authorizedDisclosureOrigins: [...new Set([...(base.authorizedDisclosureOrigins ?? []), origin])],
183	  };
184	}
185	
186	export function connectionOf(providerId: string): { connected: boolean; source?: string; external?: boolean } {
187	  const def = providerDefinition(providerId);
188	  if (!def) return { connected: false };
189	  if (providerId === "compatible") {
190	    try { providerBaseUrl("compatible"); } catch { return { connected: false }; }
191	  }
192	  const found = resolveCredential(providerId, def.credentialEnv);
193	  if (found) return { connected: true, source: found.source, external: found.kind === "external" };
194	  // A key-less compatible server (plain vLLM, llama.cpp) the operator declared with NEXUS_COMPATIBLE_AUTH=none (PRV-14).
195	  if (providerId === "compatible" && operatorSetting("NEXUS_COMPATIBLE_AUTH") === "none") return { connected: true, source: "declared key-less (NEXUS_COMPATIBLE_AUTH=none)" };
196	  return { connected: false };
197	}
198	
199	export async function buildCatalog(config: HarnessConfig, opts: { timeoutMs?: number; signal?: AbortSignal } = {}): Promise<Catalog> {
200	  const timeoutMs = opts.timeoutMs ?? 8_000;
201	  const appliance = applianceConfig(config);
202	  const applianceClient = new LocalLlmClient(appliance);
203	  const providers: CatalogProvider[] = [];
204	  const models: CatalogModel[] = [];
205	
206	  const load = async (entry: CatalogProvider, create: () => { endpoint: string; list: (signal?: AbortSignal) => Promise<string[]> }) => {
207	    let endpoint: string | undefined;
208	    try {
209	      const source = create();
210	      endpoint = source.endpoint;
211	      const ids = listedIds(await withTimeout(source.list(opts.signal), timeoutMs, opts.signal)).filter((id) => chatModel(entry.id, id));
212	      cache(cacheId(entry.id, endpoint), ids);
213	      models.push(...ids.map((id) => ({ provider: entry.id, id })));
214	    } catch (err: any) {
215	      const old = endpoint ? cached(cacheId(entry.id, endpoint)) : undefined;
216	      entry.status = old ? "cached" : "error";
217	      // Provider error text can quote the URL it called (with its userinfo or query) or echo a credential.
218	      entry.error = redactSecrets(scrubUrls(String(err?.message ?? err))).slice(0, 200);
219	      if (old) models.push(...old.map((id) => ({ provider: entry.id, id })));
220	    }
221	  };
222	
223	  const applianceEntry: CatalogProvider = {
224	    id: APPLIANCE,
225	    label: `Appliance (${originOf(appliance.endpoint)?.replace(/^https?:\/\//, "") ?? appliance.endpoint})`,
226	    disclosure: applianceClient.disclosureOf(),
227	    connected: true,
228	    methods: [],
229	    status: "ok",
230	  };
231	  providers.push(applianceEntry);
232	  const jobs: Promise<void>[] = [load(applianceEntry, () => ({ endpoint: appliance.endpoint, list: (signal) => applianceClient.listModels(signal) }))];
233	
234	  // A session run on `-e <url>` (or the environment) is on neither the appliance nor a cloud provider: list that.
235	  const sessionEndpoint = config.provider ? undefined : config.endpoint;
236	  const onSessionEndpoint = !!sessionEndpoint && !sameEndpoint(sessionEndpoint, appliance.endpoint);
237	  if (onSessionEndpoint) {
238	    const client = new LocalLlmClient(config);
239	    const host = originOf(sessionEndpoint)?.replace(/^https?:\/\//, "");
240	    const entry: CatalogProvider = {
241	      id: SESSION_ENDPOINT,
242	      label: host ? `This session (${host})` : "This session",
243	      disclosure: client.disclosureOf(),
244	      connected: true,
245	      methods: [],
246	      status: "ok",
247	    };
248	    providers.unshift(entry); // the endpoint that works heads the picker
249	    jobs.push(load(entry, () => ({ endpoint: sessionEndpoint!, list: (signal) => client.listModels(signal) })));
250	  }
251	
252	  for (const def of Object.values(PROVIDERS)) {
253	    const c = connectionOf(def.id);
254	    if (def.id === "compatible" && !c.connected) continue; // needs a base URL before it is meaningful
255	    const entry: CatalogProvider = {
256	      id: def.id,
257	      label: def.label,
258	      disclosure: "cloud",
259	      connected: c.connected,
260	      ...(c.source ? { source: c.source } : {}),
261	      ...(c.external ? { external: true } : {}),
262	      methods: def.methods,
263	      status: c.connected ? "ok" : "disconnected",
