266	    if (c.connected) jobs.push(load(entry, () => {
267	      const provider = providerConfig(config, def.id);
268	      return { endpoint: provider.endpoint, list: (signal) => new LocalLlmClient(provider).listModels(signal) };
269	    }));
270	  }
271	  await Promise.all(jobs);
272	
273	  const order = new Map(providers.map((p, i) => [p.id, i]));
274	  models.sort((a, b) => (order.get(a.provider)! - order.get(b.provider)!) || a.id.localeCompare(b.id));
275	  return {
276	    providers,
277	    models,
278	    current: { provider: config.provider ?? (onSessionEndpoint ? SESSION_ENDPOINT : APPLIANCE), model: config.model },
279	    recent: readRecent(),
