1	/**
2	 * Optional provider capabilities: context capacity, output allowance and request token counting, discovered from the
3	 * selected connection where it advertises them, and clearly labelled estimates where it does not.
4	 *
5	 * None of this is a prerequisite. A connection that advertises nothing (LM Studio, plain llama.cpp, a cloud provider)
6	 * runs on the operator's configuration or the client defaults, and every number says which it is. A connection that
7	 * advertises capacity (the homelab-ai gateway's `/v1/models`: context_length, max_completion_tokens, limits_version,
8	 * serving workers; vLLM's max_model_len) has it used, refreshed when the model, the advertised limits version, the
9	 * serving workers or the observed capacity change. A stale client default never overrides valid advertised capacity;
10	 * an operator's explicit setting below it is kept (it is a choice), above it is capped (it is not physical capacity).
11	 *
12	 * Count sources, from strongest to weakest:
13	 * - `exact_admitted`: the gateway's own count of the request it admitted (inference response headers), after the fact;
14	 * - `exact_sampled_worker`: `/v1/tokenize` applied the chat template and tokenized the actual outbound request on one
15	 *   worker of the alias. The current gateway contract samples that worker without the routing and reasoning policy
16	 *   inference applies, so it is exact for that worker and template, not proven for the worker inference admits;
17	 * - `gateway_conservative`: the gateway could not tokenize and returned its conservative estimate;
18	 * - `client_estimate`: Nexus's own estimate (no counting capability, or it is unavailable).
19	 *
20	 * The tool-output headroom kept free for the next tool results is a scheduling policy, not a measurement; it is
21	 * reported separately from the measured prompt and the advertised output allowance.
22	 */
23	
24	export type SizingSource = "advertised" | "operator" | "operator_capped_by_advertised" | "client_default";
25	export type CountSource = "exact_admitted" | "exact_sampled_worker" | "gateway_conservative" | "client_estimate";
26	export type CapabilityState = "supported" | "unsupported" | "unavailable" | "unknown";
27	
28	/** Built-in client defaults: used only when neither the provider nor the operator gives a value. */
29	export const CLIENT_DEFAULT_CONTEXT = 65_536;
30	export const CLIENT_DEFAULT_OUTPUT = 8_192;
31	/** Tool-output headroom policy: min(4096, context/8). A scheduling margin for the next tool results, not capacity. */
32	export function toolHeadroomPolicy(context: number, configured?: number): number {
33	  return configured ?? Math.min(4096, Math.floor(context / 8));
34	}
35	
36	export type ServerKind = "gateway" | "vllm" | "llamacpp" | "lmstudio" | "ollama" | "unknown";
37	
38	export interface Advertisement {
39	  /**
40	   * Who advertised: the homelab-ai gateway contract, a vLLM-style catalog, a server's own endpoint for its loaded
41	   * context (llama.cpp `/props`, LM Studio `/api/v0/models`, Ollama `/api/show`), or an OpenAI-style catalog with no limits.
42	   */
43	  via: "aihost_gateway" | "vllm" | "llamacpp" | "lmstudio" | "ollama" | "catalog";
44	  serverKind?: ServerKind;
45	  /** null: the provider says the capacity is currently unknown (e.g. no serving worker observed). */
46	  contextLength?: number | null;
47	  maxCompletionTokens?: number;
48	  limitsVersion?: string;
49	  reasoning?: { mode?: string; budget?: number };
50	  workers?: string[];
51	  /** The connection's contract includes a request-counting endpoint (/v1/tokenize). */
52	  tokenize: boolean;
53	}
54	
55	export interface ProviderCapabilities {
56	  model: string;
57	  observedAt: string;
58	  discovery: CapabilityState;
59	  discoveryDetail?: string;
60	  advertised?: Advertisement;
61	  tokenCounting: CapabilityState;
62	  tokenCountingDetail?: string;
63	  contextLimit: number;
64	  contextSource: SizingSource;
65	  outputAllowance: number;
66	  outputSource: SizingSource;
67	}
68	
69	const positiveInt = (v: unknown): number | undefined => (typeof v === "number" && Number.isFinite(v) && v > 0 ? Math.floor(v) : undefined);
70	
71	/**
72	 * Which server kind an entry positively identifies: gateway (limits_version), llama.cpp (owned_by llamacpp or
73	 * n_ctx_train meta), LM Studio (organization_owner), Ollama (library or ollama), or unknown. Generic context fields
74	 * describe capacity, not the server implementation; vLLM is identified separately with its /version response.
75	 */
76	export function serverKindOf(entry: Record<string, any> | undefined): ServerKind {
77	  if (!entry || typeof entry !== "object") return "unknown";
78	  if (typeof entry.limits_version === "string" && entry.limits_version.length > 0) return "gateway";
79	  const owner = typeof entry.owned_by === "string" ? entry.owned_by.toLowerCase() : "";
80	  if (owner === "llamacpp" || (entry.meta && typeof entry.meta === "object" && "n_ctx_train" in entry.meta)) return "llamacpp";
81	  if (owner === "organization_owner") return "lmstudio";
82	  if (owner === "library" || owner === "ollama") return "ollama";
83	  return "unknown";
84	}
85	
86	/** The vLLM GET /version contract; capacity fields in a generic model catalog are not identity evidence. */
87	export function parseVllmVersion(body: unknown): string | undefined {
88	  if (!body || typeof body !== "object" || Array.isArray(body)) return undefined;
89	  const version = (body as Record<string, unknown>).version;
90	  return typeof version === "string" && version.trim().length > 0 ? version.trim() : undefined;
91	}
92	
93	/** The Ollama GET /api/version contract; malformed or empty versions do not identify the endpoint. */
94	export function parseOllamaVersion(body: unknown): string | undefined {
95	  if (!body || typeof body !== "object" || Array.isArray(body)) return undefined;
96	  const version = (body as Record<string, unknown>).version;
97	  return typeof version === "string" && version.trim().length > 0 ? version.trim() : undefined;
98	}
99	
100	export function serverKindOfAdvertisement(ad: Advertisement | undefined): ServerKind {
101	  if (!ad) return "unknown";
102	  if (ad.via === "aihost_gateway") return "gateway";
103	  if (ad.via === "vllm") return "vllm";
104	  if (ad.via === "llamacpp") return "llamacpp";
105	  if (ad.via === "lmstudio") return "lmstudio";
106	  if (ad.via === "ollama") return "ollama";
107	  return "unknown";
108	}
109	
110	/** Reads one `/models` entry. Unknown shapes yield a catalog advertisement with no limits (never an error). */
111	export function parseAdvertisement(entry: Record<string, any> | undefined): Advertisement | undefined {
112	  if (!entry || typeof entry !== "object") return undefined;
113	  const gateway = typeof entry.limits_version === "string" && entry.limits_version.length > 0;
114	  const workers = Array.isArray(entry.serving)
115	    ? entry.serving.map((s: any) => (typeof s?.worker_id === "string" ? s.worker_id : undefined)).filter((w: string | undefined): w is string => Boolean(w)).sort()
116	    : undefined;
117	  const contextLength = entry.context_length === null ? null : positiveInt(entry.context_length) ?? positiveInt(entry.max_model_len);
118	  const reasoning = entry.reasoning && typeof entry.reasoning === "object"
119	    ? { ...(typeof entry.reasoning.mode === "string" ? { mode: entry.reasoning.mode } : {}), ...(positiveInt(entry.reasoning.budget) ? { budget: positiveInt(entry.reasoning.budget) } : {}) }
120	    : undefined;
121	  return {
122	    via: gateway ? "aihost_gateway" : "catalog",
123	    ...(contextLength !== undefined ? { contextLength } : {}),
124	    ...(positiveInt(entry.max_completion_tokens) ? { maxCompletionTokens: positiveInt(entry.max_completion_tokens) } : {}),
125	    ...(gateway ? { limitsVersion: entry.limits_version } : {}),
126	    ...(reasoning && Object.keys(reasoning).length ? { reasoning } : {}),
127	    ...(workers?.length ? { workers } : {}),
128	    tokenize: gateway,
129	  };
130	}
131	
132	/**
133	 * The context a local server says it has loaded, from its own endpoint (REQ-PRV-101): llama.cpp `GET /props`
134	 * (default_generation_settings.n_ctx: the runtime window, not the model's training size), LM Studio `GET /api/v0/models`
135	 * (loaded_context_length, else max_context_length), Ollama `POST /api/show` (the num_ctx parameter, else the model's
136	 * <arch>.context_length). Returns undefined for any other shape.
